import { FRAME_IDS } from '../src/frame-ids.ts';
import {build} from 'esbuild';
import {mkdir,readFile,writeFile,copyFile} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import {dirname,resolve,join} from 'node:path';
import {createHash} from 'node:crypto';
const root=resolve(dirname(fileURLToPath(import.meta.url)),'..');
const output=root;
const source=join(root,'src');
await mkdir(join(output,'lib'),{recursive:true});
const base={bundle:true,minify:true,sourcemap:false,legalComments:'none',target:'es2022'};
await build({...base,entryPoints:[join(source,'host.ts')],outfile:join(output,'lib/index.js'),platform:'node',format:'esm'});
await build({...base,entryPoints:[join(source,'boot.ts')],outfile:join(output,'lib/boot.js'),platform:'browser',format:'iife'});
await build({...base,entryPoints:[join(source,'renderer.ts')],outfile:join(output,'lib/renderer.js'),platform:'browser',format:'esm'});
const client=await build({...base,entryPoints:[join(source,'panel.ts')],write:false,platform:'browser',format:'cjs',external:['react','react/jsx-runtime','@deepseek-ai/dsh-client-ui-primitives']});
await writeFile(join(output,'lib/client.js'),`window.__ModuleLoader__.load({id:"dsh-boot-ocbc",factory(require){var module={exports:{}};var exports=module.exports;${client.outputFiles[0].text};return module.exports;}});`);
const indices=FRAME_IDS;
const names=[...indices.map(i=>`frames/native-${String(i).padStart(4,'0')}.webp`),'clean-plate-v1.webp','glyphs.png','glyphs.json',...[12,24,30,36].map(i=>`arrival-${i}.bin`)];
names.push('icon.svg');
const files=[];
for(const name of names){const data=await readFile(join(output,'assets',name));files.push({path:name,bytes:data.length,sha256:createHash('sha256').update(data).digest('hex')})}
await writeFile(join(output,'asset-manifest.json'),JSON.stringify({files}));
const metadata=JSON.parse(await readFile(join(output,'package.json'),'utf8'));
await writeFile(join(output,'dsh.plugin.json'),JSON.stringify({id:'dsh-external/dsh-boot-ocbc',version:metadata.version,main:'./lib/index.js',description:'OCBC startup animation',engines:{dsh:'>=0.1.7-rc.2'},contributes:{tools:[],skills:[]}},null,2)+'\n');
await writeFile(join(output,'cordis.patch.yml'),'- insert:\n    - id: dsh-boot-ocbc\n      name: dsh-boot-ocbc\n');
await copyFile(join(root,'scripts/verify-package.mjs'),join(output,'lib/verify-package.mjs'));
await copyFile(join(root,'scripts/source-files.mjs'),join(output,'lib/source-files.mjs'));
await import('./update-release.mjs');
console.log(JSON.stringify({output,assetBytes:files.reduce((s,f)=>s+f.bytes,0)}));
